function buildSheep(record){const g=new THREE.Group(),woolMat=new THREE.MeshStandardMaterial({color:0xe8e1d1,roughness:1}),faceMat=new THREE.MeshStandardMaterial({color:0x6d594b,roughness:1}),legMat=new THREE.MeshStandardMaterial({color:0x57483c,roughness:1});const body=new THREE.Mesh(new THREE.SphereGeometry(.62,10,8),woolMat);body.scale.set(1.2,.86,.9);body.position.y=.75;g.add(body);for(const [x,z,sc] of [[-.42,-.18,.38],[.4,-.18,.4],[-.38,.34,.38],[.38,.34,.4],[0,-.42,.38],[0,.48,.4]]){const curl=new THREE.Mesh(new THREE.SphereGeometry(sc,8,7),woolMat);curl.position.set(x,.95,z);g.add(curl);}const head=new THREE.Mesh(new THREE.SphereGeometry(.31,9,8),faceMat);head.position.set(0,.92,.68);g.add(head);for(const side of[-1,1]){const ear=new THREE.Mesh(new THREE.SphereGeometry(.12,7,6),faceMat);ear.scale.set(1,.45,1.5);ear.position.set(side*.3,.98,.67);g.add(ear);const leg=new THREE.Mesh(new THREE.CylinderGeometry(.07,.08,.42,6),legMat);leg.position.set(side*.34,.25,side*.18);g.add(leg);}const pen=state.sheepPens[record.penIndex],homeX=pen?.x??0,homeZ=pen?.z??0;g.position.set(homeX,groundHeight(homeX,homeZ),homeZ);scene.add(g);const visual={record,group:g,homeX,homeZ,phase:sheepVisuals.length*1.83};sheepVisuals.push(visual);return visual;}
state.sheep.forEach(buildSheep);
function updateSheep(now){for(const sheep of sheepVisuals){const a=now*.00025+sheep.phase,x=sheep.homeX+Math.sin(a)*2.1,z=sheep.homeZ+Math.cos(a*1.23)*1.45;sheep.group.position.set(x,groundHeight(x,z)+Math.abs(Math.sin(now*.004+sheep.phase))*.025,z);sheep.group.rotation.y=Math.atan2(Math.cos(a),-Math.sin(a));}}
const chickenVisuals=[];
function buildChicken(record){const g=new THREE.Group(),feather=new THREE.MeshStandardMaterial({color:0xe6dfc9,roughness:1}),wingMat=new THREE.MeshStandardMaterial({color:0xc9b99b,roughness:1}),combMat=new THREE.MeshStandardMaterial({color:0xb63a32,roughness:.8}),beakMat=new THREE.MeshStandardMaterial({color:0xd69a36,roughness:.8}),legMat=new THREE.MeshStandardMaterial({color:0x9b6232,roughness:1});const body=new THREE.Mesh(new THREE.SphereGeometry(.42,9,7),feather);body.scale.set(1.15,.78,.88);body.position.y=.48;g.add(body);const head=new THREE.Mesh(new THREE.SphereGeometry(.22,8,7),feather);head.position.set(0,.84,.34);g.add(head);const comb=new THREE.Mesh(new THREE.SphereGeometry(.1,7,6),combMat);comb.position.set(0,1.05,.31);g.add(comb);const beak=new THREE.Mesh(new THREE.ConeGeometry(.09,.22,5),beakMat);beak.rotation.x=Math.PI/2;beak.position.set(0,.8,.57);g.add(beak);for(const side of[-1,1]){const wing=new THREE.Mesh(new THREE.SphereGeometry(.23,8,6),wingMat);wing.scale.set(.48,.65,1);wing.position.set(side*.32,.5,.02);g.add(wing);const leg=new THREE.Mesh(new THREE.CylinderGeometry(.035,.045,.3,5),legMat);leg.position.set(side*.14,.16,0);g.add(leg);}const tail=new THREE.Mesh(new THREE.ConeGeometry(.17,.4,5),feather);tail.rotation.x=-Math.PI/2;tail.position.set(0,.62,-.43);g.add(tail);const coop=state.chickenCoops[record.coopIndex],homeX=coop?.x??0,homeZ=coop?.z??0;g.position.set(homeX,groundHeight(homeX,homeZ),homeZ);scene.add(g);const visual={record,group:g,homeX,homeZ,phase:chickenVisuals.length*2.17};chickenVisuals.push(visual);return visual;}
state.chickens.forEach(buildChicken);
function updateChickens(now){for(const chicken of chickenVisuals){const a=now*.00042+chicken.phase,x=chicken.homeX+Math.sin(a)*1.75,z=chicken.homeZ+Math.cos(a*1.31)*1.25;chicken.group.position.set(x,groundHeight(x,z)+Math.abs(Math.sin(now*.006+chicken.phase))*.035,z);chicken.group.rotation.y=Math.atan2(Math.cos(a),-Math.sin(a));}}

const placementPreview=new THREE.Group(),previewRing=new THREE.Mesh(new THREE.RingGeometry(.75,1.05,32),new THREE.MeshBasicMaterial({color:0x8fe0a0,side:THREE.DoubleSide,transparent:true,opacity:.9}));previewRing.rotation.x=-Math.PI/2;placementPreview.add(previewRing);placementPreview.visible=false;scene.add(placementPreview);
 // Delimitação visual da área escolhida pelo jogador; não modifica o terreno natural.
 const plotMarker=new THREE.Group(),plotPostMat=new THREE.MeshStandardMaterial({color:0xd7b36e,roughness:.85}),plotRopeMat=new THREE.LineBasicMaterial({color:0xe4c98e,transparent:true,opacity:.9});
 for(const [sx,sz] of [[-10,-10],[10,-10],[10,10],[-10,10]]){const post=new THREE.Mesh(new THREE.CylinderGeometry(.11,.15,1.55,6),plotPostMat);post.position.set(sx,.78,sz);plotMarker.add(post);}
 const plotPoints=[[-10,.42,-10],[10,.42,-10],[10,.42,10],[-10,.42,10],[-10,.42,-10]].map(p=>new THREE.Vector3(...p));plotMarker.add(new THREE.Line(new THREE.BufferGeometry().setFromPoints(plotPoints),plotRopeMat));plotMarker.visible=false;scene.add(plotMarker);
 function showPlotMarker(x,z){plotMarker.position.set(x,groundHeight(x,z),z);plotMarker.visible=true;}
 plotMarker.visible=false;
 const dialogueScripts={alina:["Bom dia, viajante. Você parece exausto. O que aconteceu com você?","Minha aldeia foi atacada por bárbaros... Perdi tudo e não sei se alguém conseguiu sobreviver.","Sinto muito. Meu nome é Alina, sou a anciã desta Vila Vizinha. Aqui você poderá descansar um pouco e recuperar as forças.","Há terras livres neste vale. Você poderá escolher qualquer pedaço de terra para construir um abrigo e formar sua própria vila novamente.","Mas há uma obrigação: essas terras pertencem ao rei. Todos os anos você deverá pagar ao reino pelo terreno que estiver usando.","Comece com cuidado. Não receberá uma vila pronta: cada ferramenta, cada construção e cada conquista virá do seu próprio trabalho. Quando precisar de orientação, procure-me."],tomas:["Sou Tomas, o ferreiro desta vila. Trabalho o metal e conserto ferramentas para quem traz os materiais necessários.","Um bom machado ou uma picareta exige minério, combustível e muito trabalho. Nada surge do nada, rapaz.","Quando você tiver os recursos e construir sua própria oficina, poderá aprender a produzir ferramentas melhores."],edda:["Meu nome é Edda. Cuido das pequenas plantações e conheço os ciclos da terra.","Antes de semear, prepare o solo e consiga sementes. Cada estação tem seu tempo, e uma colheita exige paciência.","Quando tiver seu próprio terreno e as ferramentas adequadas, posso lhe explicar mais sobre o cultivo."],martim:["Pode me chamar de Martim. Viajo entre povoados e negocio mercadorias quando há algo para trocar.","O comércio pode ajudar uma comunidade a prosperar, mas primeiro é preciso produzir, coletar ou comprar aquilo que será negociado.","Quando sua vila estiver de pé, procure um entreposto e teremos muito o que conversar."],bruna:["Sou Bruna. Costuro roupas e remendo tecidos para os moradores daqui.","Fios, couro e tecido têm valor. Aprender a aproveitar cada material será importante quando você construir seu próprio lar.","Por enquanto, observe como trabalhamos. Uma vila forte começa com pessoas que sabem fazer coisas diferentes."],lia:["Meu nome é Lia. Tenho viajado sozinha desde que perdi meu antigo lar.","Ouvi dizer que alguém está reconstruindo uma comunidade neste vale. Procuro um lugar seguro para recomeçar.","Se você já construiu um abrigo, posso deixar a estrada e viver na sua vila. Gostaria de aceitar meu convite?"],bento:["Sou Bento. Sei trabalhar duro, mas ainda não encontrei um lugar para chamar de casa.","Não pertenço a nenhuma das vilas daqui. Estou procurando alguém que esteja começando uma comunidade própria.","Se houver um abrigo construído, quero me juntar à sua vila e ajudar no que for preciso. Posso ir com você?"],mara:["Pode me chamar de Mara. Viajo entre os povoados e procuro um novo começo.","Ainda não tenho uma casa nem um compromisso com outra vila. Quero fazer parte de uma comunidade que esteja nascendo.","Se você já ergueu um abrigo, gostaria de morar na sua vila. Você me recebe?"]};
 let dialogueIndex=0,dialogueOpen=false,activeNpc=null,activeDialogueLines=[],currentInteractable=null;
 function closeDialogue(){dialogue.hidden=true;dialogueOpen=false;if(activeNpc?.id==="old-survivor"&&!state.survivorQuest.found){state.survivorQuest.found=true;const survivor=villagers.find(v=>v.id==="old-survivor");if(survivor){survivor.followingPlayer=true;survivor.group.visible=true;}notify("Darian vai acompanhar você. Leve-o até Alina na Vila Vizinha.");saveState();objective.querySelector("strong").textContent="Leve Darian até Alina";objective.querySelector("p").textContent="O sobrevivente está seguindo você. Volte à Vila Vizinha sem deixá-lo para trás.";}if(activeNpc?.id==="old-survivor"&&state.rescuePrep.reported&&!state.rescuePlan.darianBriefed){state.rescuePlan.darianBriefed=true;saveState();notify("Darian compartilhou o que sabe sobre o interior do posto.");}if(activeNpc?.id?.startsWith("rescued-")&&state.prisonerRescue.completed){if(!state.rescueDebrief.survivorReports.includes(activeNpc.id)){state.rescueDebrief.survivorReports.push(activeNpc.id);saveState();notify(activeNpc.name.split(" · ")[0]+" compartilhou seu relato. "+state.rescueDebrief.survivorReports.length+"/3 relatos ouvidos.");}}if(activeNpc?.id==="old-survivor"&&state.rescueDebrief.alinaReceived&&!state.rescueDebrief.darianRecognized){state.rescueDebrief.darianRecognized=true;state.rescueDebrief.nextLead=true;saveState();notify("Darian reconheceu o local: Fortaleza de Pedra Negra. Nova pista registrada no diário.");}if(activeNpc?.id==="alina"){if(state.prisonerRescue.completed&&state.rescueDebrief.survivorReports.length>=3&&!state.rescueDebrief.alinaReceived){state.rescueDebrief.alinaReceived=true;saveState();notify("Alina acolheu os três sobreviventes e ouviu seus relatos.");}state.alinaTalked=true;if(state.rescuePrep.reported&&!state.rescuePlan.briefing){state.rescuePlan.briefing=true;notify("Plano de resgate registrado no diário. Prepare seu equipamento.");}if(state.mainQuest.clues.length>=3&&!state.mainQuest.reported){state.mainQuest.reported=true;notify("Investigação concluída. As pistas foram entregues a Alina.");}if(state.survivorQuest.returned&&state.prisonerQuest.clues.length>=3&&!state.prisonerQuest.reported){state.prisonerQuest.reported=true;notify("Alina recebeu as pistas. O Posto da Garganta foi localizado.");}if(state.prisonerQuest.reported&&state.rescuePrep.clues.length>=4&&!state.rescuePrep.reported){state.rescuePrep.reported=true;notify("Preparação concluída. Alina agora conhece a entrada, a guarda e os horários do posto.");}if(state.survivorQuest.found&&!state.survivorQuest.returned&&Math.hypot(player.x-alinaX,player.z-alinaZ)<=7){state.survivorQuest.returned=true;const survivor=villagers.find(v=>v.id==="old-survivor");if(survivor){survivor.followingPlayer=false;survivor.group.visible=true;survivor.route=[[alinaX+3,alinaZ+3],[alinaX+4,alinaZ+3],[alinaX+4,alinaZ+4],[alinaX+3,alinaZ+4]];survivor.index=0;}notify("Darian está em segurança. Alina vai cuidar dele.");}saveState();objective.querySelector("strong").textContent=state.rescuePrep.reported?"Preparação do resgate concluída":state.prisonerQuest.reported?"Investigue o Posto da Garganta":state.survivorQuest.returned?"Siga os rastros da caravana":state.survivorQuest.found?"Leve Darian até Alina":state.mainQuest.reported?"Procure sobreviventes da antiga aldeia":state.mainQuest.clues.length>=3?"Volte à Vila Vizinha e fale com Alina":"Investigue os rastros dos bárbaros";objective.querySelector("p").textContent=state.rescuePrep.reported?"Você conhece a entrada discreta, a quantidade de guardas, os suprimentos e os horários de patrulha.":state.prisonerQuest.reported?"Investigue quatro pontos no Posto da Garganta e volte a falar com Alina.":state.survivorQuest.returned?"Encontre três pistas a leste do vale e volte para conversar com Alina.":state.survivorQuest.found?"O sobrevivente está seguindo você. Volte à Vila Vizinha.":state.mainQuest.reported?"Procure um esconderijo ao norte do vale.":"Explore o vale e procure os sinais deixados pelos invasores.";}if(state.prisonerRescue.completed){objective.querySelector("strong").textContent=state.rescueDebrief.nextLead?"A Fortaleza de Pedra Negra foi identificada":state.rescueDebrief.alinaReceived?"Converse com Darian sobre Vargan":state.rescueDebrief.survivorReports.length>=3?"Volte a falar com Alina":"Ouça os relatos dos sobreviventes";objective.querySelector("p").textContent=state.rescueDebrief.nextLead?"Darian reconheceu a fortaleza mencionada por Oren. Investigue a passagem rochosa a nordeste.":state.rescueDebrief.alinaReceived?"Darian pode confirmar o que sabe sobre a Fortaleza de Pedra Negra.":state.rescueDebrief.survivorReports.length>=3?"Alina precisa ouvir o que os três sobreviventes descobriram.":"Converse com Elara, Garen e Oren na Vila Vizinha e depois procure Alina.";}notify("Conversa concluída.");activeNpc=null;}
 function openDialogue(npc){if(dialogueOpen||!npc)return;activeNpc=npc;activeDialogueLines=npc.id==="old-survivor"&&state.rescueDebrief.alinaReceived&&!state.rescueDebrief.darianRecognized?["Darian, um dos sobreviventes mencionou uma fortaleza onde Vargan pode estar reunindo suas tropas.","Eu ouvi esse nome antes. Pedra Negra fica além da passagem rochosa, a nordeste. Vargan costumava enviar mensageiros para lá. Se ele está reunindo soldados, é lá que devemos procurar.","Precisamos confirmar a localização antes de partir. A fortaleza será muito mais perigosa que o posto. Vou marcar essa descoberta no diário."]:npc.id==="rescued-0"?["Meu nome é Elara. Obrigada por nos tirar daquele lugar. Achei que nunca mais veria o céu livre.","Vargan visitava o posto e perguntava por mapas e rotas antigas. Ele parecia procurar uma passagem para mover um grande grupo de soldados."]:npc.id==="rescued-1"?["Sou Garen. Ainda escuto os gritos dos guardas quando fecho os olhos.","Ouvi os soldados dizerem que Vargan recebeu ordens de reunir homens e suprimentos numa fortaleza de pedra. Não sei onde fica, mas Oren ouviu mais."]:npc.id==="rescued-2"?["Meu nome é Oren. Fui mantido perto da sala dos mapas e consegui ouvir parte das conversas dos oficiais.","Vargan não pretende permanecer no Posto da Garganta. Ele está reunindo tropas na Fortaleza de Pedra Negra, além da passagem rochosa, a nordeste. Ouvi que partirá assim que todos os soldados chegarem."]:npc.id==="alina"&&state.prisonerRescue.completed&&!state.rescueDebrief.alinaReceived&&state.rescueDebrief.survivorReports.length>=3?["Os três chegaram vivos! A Vila Vizinha lhes dará abrigo e tempo para se recuperar. Você fez algo que jamais esqueceremos.","Elara, Garen e Oren têm relatos importantes. Ouça cada um deles com calma. Oren parece ter descoberto algo sobre os planos de Vargan.","Quando reunir os três relatos, volte a falar comigo. Precisamos entender o que ele está preparando."]:npc.id==="old-survivor"&&state.rescuePrep.reported&&state.survivorQuest.returned&&!state.rescuePlan.darianBriefed?["Agora que sabemos onde os prisioneiros estão, posso contar o que vi antes de fugir.","O posto tem um corredor interno que leva às celas. Os guardas costumam se reunir perto do depósito durante a troca de turno. Evite fazer barulho: os prisioneiros estão assustados e qualquer alarme pode colocar todos em perigo.","Não sei quantos prisioneiros ainda estão vivos, mas ouvi Vargan dizer que seriam transferidos em breve. Precisamos agir com cuidado."]:npc.id==="old-survivor"?["Não se aproxime! Meu nome é Darian. Fugi quando os bárbaros atacaram nossa aldeia e estou escondido aqui desde então.","Vi os invasores levarem prisioneiros para o leste. O comandante deles se chama Vargan. Não posso continuar sozinho. Você pode me levar até a Vila Vizinha?"]:npc.id==="alina"&&state.rescuePrep.reported&&!state.rescuePlan.briefing?["As informações que você trouxe são valiosas. O Posto da Garganta tem seis guardas, mas conhecemos uma passagem discreta e os horários de troca das patrulhas.","Não podemos partir despreparados. Você precisará de uma lança, uma tocha, provisões para a viagem e roupas adequadas. Não retire nada do esconderijo inimigo: ainda está vigiado.","Converse também com Darian. Ele viu parte do interior do posto antes de fugir. Quando estiver equipado e tiver ouvido o relato dele, abra o diário e confirme que está pronto."]:npc.id==="alina"&&state.survivorQuest.returned&&state.prisonerQuest.clues.length>=3&&!state.prisonerQuest.reported?["As marcas que você encontrou confirmam a rota da caravana. Este documento menciona o Posto da Garganta, a leste daqui.","É uma antiga posição de vigia dos bárbaros. Os prisioneiros devem estar sendo mantidos lá, mas não tente entrar sem preparo.","Precisaremos planejar o resgate com cuidado. Vou guardar essas informações e registrar o local no diário."]:npc.id==="alina"&&state.survivorQuest.found&&!state.survivorQuest.returned?["Você conseguiu encontrar alguém! Darian, está seguro agora. Vamos abrigá-lo na Vila Vizinha.","Ele confirma que os bárbaros levaram prisioneiros para o leste. Precisamos descobrir para onde foram. Esta história ainda não terminou."]:npc.id==="alina"&&state.mainQuest.clues.length>=3&&!state.mainQuest.reported?["Alina, encontrei sinais da passagem dos bárbaros, um acampamento abandonado e um documento deixado para trás.","Essas marcas confirmam que os invasores seguiram para o leste. O documento menciona um comandante chamado Vargan.","Guarde essas pistas. Ainda precisamos descobrir onde Vargan está e se há sobreviventes da sua aldeia. Esta investigação está apenas começando."]:(dialogueScripts[npc.id]||[]);if(!activeDialogueLines.length)return;dialogueOpen=true;dialogueIndex=0;dialogue.hidden=false;talkPrompt.hidden=true;dialogueSpeaker.textContent=npc.name;dialogueText.textContent=activeDialogueLines[dialogueIndex];dialogueNext.textContent="CONTINUAR";}
 function advanceDialogue(){if(!dialogueOpen)return;if(activeNpc?.recruitable&&dialogueIndex===activeDialogueLines.length-1){if(activeNpc.recruitmentBlocked){closeDialogue();return;}if(!state.shelters.length){dialogueText.textContent="Antes de receber moradores, construa seu primeiro abrigo. Quando ele estiver pronto, volte a conversar comigo.";activeNpc.recruitmentBlocked=true;dialogueNext.textContent="ENTENDI";return;}if(state.recruitedVillagers.length+state.familyChildren.filter(child=>child.stage!=="adult").length>=housingCapacity()){dialogueText.textContent="Sua vila está sem espaço para novos moradores. Construa uma casa para ampliar a capacidade e depois volte a conversar.";activeNpc.recruitmentBlocked=true;dialogueNext.textContent="ENTENDI";return;}const resident=villagers.find(v=>v.id===activeNpc.id);if(resident&&!resident.recruited){const slot=state.recruitedVillagers.length,home=slot<state.shelters.length*3?state.shelters[Math.floor(slot/3)]:state.villageHouses[Math.floor((slot-state.shelters.length*3)/3)],offsetX=(slot%3-1)*2.8,offsetZ=3+Math.floor(slot/3)*2.8,x=home.x+offsetX,z=home.z+offsetZ;resident.recruited=true;if(resident.recruitMarker)resident.recruitMarker.visible=false;resident.route=[[x,z],[x+1.5,z],[x+1.5,z+1.5],[x,z+1.5]];resident.index=0;resident.group.position.set(x,groundHeight(x,z),z);state.recruitedVillagers.push(resident.id);saveState();const residentName=resident.name.split(" · ")[0];activeNpc.recruitable=false;closeDialogue();notify(residentName+" agora faz parte da sua vila. Habitantes recrutados: "+state.recruitedVillagers.length+".");return;}closeDialogue();return;}dialogueIndex++;if(dialogueIndex>=activeDialogueLines.length){closeDialogue();return;}dialogueText.textContent=activeDialogueLines[dialogueIndex];dialogueNext.textContent=dialogueIndex===activeDialogueLines.length-1?(activeNpc?.recruitable?"CONVIDAR PARA SUA VILA":"ENCERRAR CONVERSA"):"CONTINUAR";}
 talkButton.addEventListener("click",()=>{if(currentInteractable?.id==="rufus")openChickenMarket();else if(currentInteractable?.id==="shepherd")openSheepMarket();else if(currentInteractable?.id==="bruna")openTailor();else openDialogue(currentInteractable);});dialogueNext.addEventListener("click",advanceDialogue);
 const residentJobs=[
  {id:"general",label:"Ajudante geral",needs:()=>true,area:"shelter"},
  {id:"gatherer",label:"Coletor de recursos",needs:()=>true,area:"shelter"},
  {id:"woodcutter",label:"Lenhador",needs:()=>state.tools.axe||state.tools.axeAdvanced,area:"shelter"},
  {id:"hunter",label:"Caçador",needs:()=>state.tools.spear,area:"shelter"},
  {id:"farmer",label:"Agricultor",needs:()=>!!state.tools.hoe&&state.fields.length>0,area:"field"},
  {id:"rancher",label:"Criador de animais",needs:()=>state.chickenCoops.length>0||state.sheepPens.length>0,area:"animals"},
  {id:"artisan",label:"Artesão",needs:()=>state.workbenches.length>0||state.carpentryShops.length>0||state.tailoringShops.length>0||state.looms.length>0,area:"workshop"},
  {id:"miller",label:"Moleiro",needs:()=>state.mills.length>0,area:"mill"},
  {id:"baker",label:"Padeiro",needs:()=>state.bakeries.length>0,area:"bakery"},
  {id:"tavernkeeper",label:"Taverneiro",needs:()=>state.taverns.length>0,area:"tavern"},
  {id:"trader",label:"Comerciante",needs:()=>state.marketStalls.length>0,area:"market"},
  {id:"guard",label:"Guarda da vila",needs:()=>state.defensiveStructures.length>0,area:"guard"},
  {id:"builder",label:"Construtor",needs:()=>state.shelters.length>0,area:"shelter"}
 ];
 function residentWorkRoute(id,job,slot){
  const role=residentJobs.find(item=>item.id===job)||residentJobs[0];let anchor=state.shelters[0]||state.selectedPlot||{x:0,z:35};
  if(role.area==="field"&&state.fields[0])anchor=state.fields[0];
  if(role.area==="animals")anchor=state.chickenCoops[0]||state.sheepPens[0]||anchor;
  if(role.area==="workshop")anchor=state.tailoringShops[0]||state.carpentryShops[0]||state.looms[0]||state.workbenches[0]||anchor;if(role.area==="mill"&&state.mills[0])anchor=state.mills[0];if(role.area==="bakery"&&state.bakeries[0])anchor=state.bakeries[0];if(role.area==="tavern"&&state.taverns[0])anchor=state.taverns[0];if(role.area==="market"&&state.marketStalls[0])anchor=state.marketStalls[0];if(role.area==="guard"&&state.defensiveStructures[0])anchor=state.defensiveStructures[0];
  const x=Number.isFinite(anchor.x)?anchor.x:0,z=Number.isFinite(anchor.z)?anchor.z:35,offset=(slot%3-1)*1.35,depth=2.8+Math.floor(slot/3)*1.25,cx=x+offset,cz=z+depth;
  return [[cx,cz],[cx+1.15,cz],[cx+1.15,cz+1.15],[cx,cz+1.15]];
 }
 function applyResidentJob(resident,job){
  const slot=state.recruitedVillagers.indexOf(resident.id),route=residentWorkRoute(resident.id,job,Math.max(0,slot));
  resident.route=route;resident.index=0;resident.group.position.set(route[0][0],groundHeight(route[0][0],route[0][1]),route[0][1]);
 }
 let tavernNightActive=null;function updateTavernSchedule(){const night=state.minute>=1080||state.minute<360;if(night===tavernNightActive)return;tavernNightActive=night;if(!state.taverns.length)return;for(const id of state.recruitedVillagers){const resident=villagers.find(v=>v.id===id);if(!resident)continue;if(night){const tavern=state.taverns[0],slot=state.recruitedVillagers.indexOf(id),side=(slot%4)-1.5,depth=5.2+Math.floor(slot/4)*1.4,x=tavern.x+side*1.25,z=tavern.z+depth;resident.route=[[x,z],[x+1,z],[x+1,z+.8],[x,z+.8]];resident.index=0;}else applyResidentJob(resident,state.villagerJobs[id]||"general");}}
