 function residentHomeInfo(id){const slot=state.recruitedVillagers.indexOf(id);if(slot<0)return null;const shelterBeds=state.shelters.length*3;if(slot<shelterBeds){const index=Math.floor(slot/3);return state.shelters[index]?{label:"Abrigo "+(index+1),kind:"abrigo"}:null;}const index=Math.floor((slot-shelterBeds)/3);return state.villageHouses[index]?{label:"Casa "+(index+1),kind:"casa"}:null;}
 function residentWellbeing(id){let data=state.villagerWellbeing[id];if(!data||typeof data!=="object"){data={happiness:70,fed:false,housed:!!residentHomeInfo(id),social:false,lastDay:state.day};state.villagerWellbeing[id]=data;}data.happiness=clamp(Number.isFinite(data.happiness)?data.happiness:70,0,100);return data;}
 function wellbeingLabel(value){return value>=85?"Muito feliz":value>=70?"Feliz":value>=50?"Regular":value>=30?"Insatisfeito":"Muito insatisfeito";}
 function familyFoodAvailable(key,amount){return (state.villageStock[key]||0)+state.barns.reduce((n,b)=>n+(b.inventory?.[key]||0),0)>=amount;}
 function takeFamilyFood(key,amount){let left=amount,take=Math.min(left,state.villageStock[key]||0);state.villageStock[key]=(state.villageStock[key]||0)-take;left-=take;for(const barn of state.barns){if(left<=0)break;const have=barn.inventory?.[key]||0,t=Math.min(left,have);barn.inventory[key]=have-t;left-=t;}return left===0;}
 function takeFamilyRation(){for(const key of["stews","meals","bread"]){if(familyFoodAvailable(key,1)){takeFamilyFood(key,1);return true;}}if(familyFoodAvailable("berries",2)){takeFamilyFood("berries",2);return true;}return false;}
 function familyOccupiedBeds(){return state.recruitedVillagers.length+state.familyChildren.filter(child=>child.stage!=="adult").length;}
