 const marketGoods={wood:{label:"Madeira",buy:6},branches:{label:"Galhos",buy:2},stones:{label:"Pedras",buy:4},fiber:{label:"Fibras",buy:3},wheat:{label:"Trigo",buy:5},wheatSeeds:{label:"Sementes",buy:7},meat:{label:"Carne",buy:9},hide:{label:"Couro",buy:8},eggs:{label:"Ovos",buy:6},wool:{label:"Lã",buy:12},planks:{label:"Tábuas",buy:11},flour:{label:"Farinha",buy:8},bread:{label:"Pães",buy:9},stews:{label:"Ensopados",buy:15},berries:{label:"Bagas",buy:3},meals:{label:"Refeições",buy:12},thread:{label:"Fios",buy:14},fabric:{label:"Tecidos",buy:24}};
