 function addVillageLog(message){state.villageProductionLog.push("Dia "+state.day+": "+message);state.villageProductionLog=state.villageProductionLog.slice(-12);}
 function produceVillageDay(day){
  const stock=state.villageStock,workers=state.recruitedVillagers;
  function takeVillageWheat(amount){let remaining=amount,fromStock=Math.min(stock.wheat,remaining);stock.wheat-=fromStock;remaining-=fromStock;for(const barn of state.barns){if(remaining<=0)break;const have=barn.inventory?.wheat||0,take=Math.min(have,remaining);barn.inventory.wheat=have-take;remaining-=take;}return remaining===0;}function takeVillageFood(key,amount){let remaining=amount,fromStock=Math.min(stock[key]||0,remaining);stock[key]=(stock[key]||0)-fromStock;remaining-=fromStock;for(const barn of state.barns){if(remaining<=0)break;const have=barn.inventory?.[key]||0,take=Math.min(have,remaining);barn.inventory[key]=have-take;remaining-=take;}return remaining===0;}
  for(const id of workers){
   const job=state.villagerJobs[id]||"general",resident=villagers.find(v=>v.id===id),name=resident?resident.name.split(" · ")[0]:id,morale=residentWellbeing(id).happiness;
   if(morale<30&&day%2===0){addVillageLog(name+" está muito insatisfeito e teve sua produtividade reduzida.");continue;}
   if(job==="gatherer"){stock.branches+=1;stock.stones+=1;stock.fiber+=1;addVillageLog(name+" coletou 1 galho, 1 pedra e 1 fibra.");}
   else if(job==="woodcutter"&&(state.tools.axe||state.tools.axeAdvanced)){stock.wood+=2;stock.branches+=1;addVillageLog(name+" trouxe 2 madeiras e 1 galho.");}
   else if(job==="hunter"&&state.tools.spear){stock.meat+=1;stock.hide+=1;addVillageLog(name+" voltou da caça com 1 carne e 1 couro.");}
   else if(job==="farmer"&&state.tools.hoe){
    let harvested=0,barnStoredWheat=0,barnStoredSeeds=0;
    for(const field of state.fields){if(field.plantedDay!==null&&field.plantedDay!==undefined&&day-field.plantedDay>=2){field.plantedDay=null;const barn=state.barns.find(item=>storageUsed(item)<1200);if(barn){const free=1200-storageUsed(barn),wheat=Math.min(5,free);barn.inventory.wheat=(barn.inventory.wheat||0)+wheat;barnStoredWheat+=wheat;const seed=free-wheat>0?1:0;if(seed){barn.inventory.wheatSeeds=(barn.inventory.wheatSeeds||0)+seed;barnStoredSeeds+=seed;}stock.wheat+=5-wheat;stock.wheatSeeds+=1-seed;}else{stock.wheat+=5;stock.wheatSeeds+=1;}harvested++;const visual=placedFields.find(entry=>entry.data===field);if(visual)refreshFieldVisual(visual);}}
    if(harvested)addVillageLog(name+" colheu "+harvested+" canteiro(s): "+(harvested*5)+" trigos e "+harvested+" sementes."+(barnStoredWheat||barnStoredSeeds?" Depositou no celeiro "+barnStoredWheat+" trigos e "+barnStoredSeeds+" sementes.":""));
   }
   else if(job==="artisan"&&state.carpentryShops.length&&stock.wood>=3){stock.wood-=3;stock.planks+=2;addVillageLog(name+" fabricou 2 tábuas usando 3 madeiras do estoque.");}
   else if(job==="miller"&&state.mills.length&&takeVillageWheat(2)){const millBarn=state.barns.find(b=>storageUsed(b)<1200);if(millBarn){millBarn.inventory.flour=(millBarn.inventory.flour||0)+1;addVillageLog(name+" moeu 2 trigos e armazenou 1 farinha no celeiro.");}else{stock.flour=(stock.flour||0)+1;addVillageLog(name+" moeu 2 trigos e produziu 1 farinha para o estoque da vila.");}}else if(job==="baker"&&state.bakeries.length){const flourAvailable=(stock.flour||0)+state.barns.reduce((n,b)=>n+(b.inventory.flour||0),0),eggsAvailable=(stock.eggs||0)+state.barns.reduce((n,b)=>n+(b.inventory.eggs||0),0);if(flourAvailable>=1&&eggsAvailable>=1){if(stock.flour>0)stock.flour--;else{const barn=state.barns.find(b=>b.inventory.flour>0);if(barn)barn.inventory.flour--;}if(stock.eggs>0)stock.eggs--;else{const barn=state.barns.find(b=>b.inventory.eggs>0);if(barn)barn.inventory.eggs--;}const bakeryBarn=state.barns.find(b=>storageUsed(b)<1200);if(bakeryBarn)bakeryBarn.inventory.bread=(bakeryBarn.inventory.bread||0)+2;else stock.bread=(stock.bread||0)+2;addVillageLog(name+" assou 2 pães usando 1 farinha e 1 ovo.");}}else if(job==="tavernkeeper"&&state.taverns.length){const ingredients=["meat","eggs","bread"],available=ingredients.every(key=>(stock[key]||0)+state.barns.reduce((n,b)=>n+(b.inventory?.[key]||0),0)>=1);if(available){ingredients.forEach(key=>takeVillageFood(key,1));const tavernBarn=state.barns.find(b=>storageUsed(b)<1200);if(tavernBarn)tavernBarn.inventory.stews=(tavernBarn.inventory.stews||0)+2;else stock.stews=(stock.stews||0)+2;addVillageLog(name+" preparou 2 ensopados usando 1 carne, 1 ovo e 1 pão.");}}else if(job==="trader"&&state.marketStalls.length){const key=Object.keys(marketGoods).find(item=>(stock[item]||0)>0);if(key){stock[key]--;const earned=marketSellPrice(key);state.coins+=earned;addMarketLog(name+" vendeu 1 "+marketGoods[key].label.toLowerCase()+" por "+earned+" moedas.");addVillageLog(name+" negociou 1 "+marketGoods[key].label.toLowerCase()+" e trouxe "+earned+" moedas.");}}
  }
  if(workers.some(id=>(state.villagerJobs[id]||"general")==="rancher")){
   let collected=0;
   for(const coop of state.chickenCoops){const eggs=Math.max(0,Math.floor(coop.eggs||0));if(eggs){stock.eggs+=eggs;coop.eggs=0;collected+=eggs;}}
   let wool=0;for(const sheep of state.sheep){if(sheep.woolReady){stock.wool+=2;sheep.woolReady=false;wool+=2;}}
   if(collected||wool)addVillageLog("Criador recolheu "+collected+" ovo(s) e "+wool+" lã do plantel.");
   let fed=0,spent=0;
   for(const hen of state.chickens){if(hen.fedDay!==day&&takeVillageWheat(1)){hen.fedDay=day;fed++;spent++;}}
   for(const sheep of state.sheep){if((sheep.fedDay===null||sheep.fedDay===undefined)&&takeVillageWheat(2)){sheep.fedDay=day;fed++;spent+=2;}}
   if(fed)addVillageLog("Criador alimentou "+fed+" animal(is), usando "+spent+" trigo(s).");
  }
  let fedCount=0,housedCount=0,socialCount=0,totalHappiness=0;
  for(const id of workers){const well=residentWellbeing(id),home=residentHomeInfo(id);let ration="";if(takeVillageFood("stews",1))ration="ensopado";else if(takeVillageFood("meals",1))ration="refeição";else if(takeVillageFood("bread",1))ration="pão";else if(takeVillageFood("berries",2))ration="2 bagas";well.fed=!!ration;well.housed=!!home;well.social=state.taverns.length>0;let change=2+(well.fed?10:-18)+(well.housed?6:-12)+(well.social?4:0);const job=state.villagerJobs[id]||"general",role=residentJobs.find(item=>item.id===job);if(job!=="general"&&role&&role.needs())change+=2;well.happiness=clamp(well.happiness+change,0,100);well.lastDay=day;if(well.fed)fedCount++;if(well.housed)housedCount++;if(well.social)socialCount++;totalHappiness+=well.happiness;}
  if(workers.length)addVillageLog("Bem-estar: "+fedCount+"/"+workers.length+" alimentados, "+housedCount+" com moradia, "+socialCount+" com convívio na taverna · felicidade média "+Math.round(totalHappiness/workers.length)+"%.");
  state.lastVillageProductionDay=day;
 }
 function processVillageProduction(){
  processFamilyDays(state.day);
  if(!Array.isArray(state.recruitedVillagers)||!state.recruitedVillagers.length){state.lastVillageProductionDay=state.day;return;}
  const first=Math.max(state.lastVillageProductionDay+1,state.day-30);
  for(let day=first;day<=state.day;day++)produceVillageDay(day);
  if(!villagePanel.hidden)renderVillagePanel();if(!marketPanel.hidden)renderMarket();
 }
