 document.getElementById("family-marry").addEventListener("click",()=>{const select=document.getElementById("family-partner"),id=select.value,resident=villagers.find(v=>v.id===id),well=id?residentWellbeing(id):null;if(state.family.spouse){document.getElementById("family-status").textContent="Você já formou sua família.";return;}if(!id||!state.recruitedVillagers.includes(id)||!resident){document.getElementById("family-status").textContent="Escolha um morador da sua vila.";return;}if(!familyHome()||familyOccupiedBeds()>=housingCapacity()){document.getElementById("family-status").textContent="Construa uma moradia e reserve espaço para a próxima geração.";return;}if(well.happiness<75){document.getElementById("family-status").textContent="A felicidade desse morador precisa chegar a pelo menos 75%.";return;}if(!familyFoodAvailable("bread",4)||!familyFoodAvailable("berries",4)){document.getElementById("family-status").textContent="A celebração exige 4 pães e 4 bagas, guardados no estoque da vila ou no celeiro.";return;}takeFamilyFood("bread",4);takeFamilyFood("berries",4);state.family.spouse=id;state.family.marriageDay=state.day;state.family.childDueDay=state.day+30;state.family.childId=null;saveState();renderFamilyPanel();document.getElementById("family-status").textContent="Você e "+resident.name.split(" · ")[0]+" formaram uma família. Agora cuidem da vila e preparem espaço para a próxima geração.";});
 villageResidents.addEventListener("change",event=>{const select=event.target.closest("select[data-resident-job]");if(!select)return;const id=select.dataset.residentJob,job=residentJobs.find(item=>item.id===select.value),resident=villagers.find(v=>v.id===id);if(!state.recruitedVillagers.includes(id)||!job||!resident)return;if(!job.needs()){villageStatus.textContent="Para essa profissão, primeiro construa a estrutura ou fabrique a ferramenta necessária.";renderVillagePanel();return;}state.villagerJobs[id]=job.id;applyResidentJob(resident,job.id);saveState();villageStatus.textContent=resident.name.split(" · ")[0]+" agora trabalha como "+job.label.toLowerCase()+". A rotina foi atualizada.";renderVillagePanel();});
document.getElementById("village-withdraw").addEventListener("click",()=>{const stock=state.villageStock;const keys=["wood","planks","branches","stones","fiber","wheat","wheatSeeds","flour","bread","stews","berries","meals","meat","hide","eggs","wool"];let moved=0;for(const key of keys){const amount=Math.max(0,Math.floor(stock[key]||0));if(amount){state.inventory[key]=(state.inventory[key]||0)+amount;stock[key]=0;moved+=amount;}}saveState();renderCrafting();renderVillagePanel();villageStatus.textContent=moved?"Você transferiu "+moved+" unidade(s) do estoque da vila para a mochila.":"O estoque da vila está vazio.";});

