const barnStorageKeys=["wheat","wheatSeeds","flour","bread","stews","berries","meals","meat","eggs"];
function storageUsed(chest){return Object.values(chest.inventory||{}).reduce((sum,value)=>sum+Math.max(0,Number(value)||0),0);}
function renderStorage(){if(!activeStorageChest)return;const warehouse=!!activeStorageChest.isWarehouse,barn=!!activeStorageChest.isBarn,used=storageUsed(activeStorageChest),keys=barn?barnStorageKeys:Object.keys(storageLabels);Array.from(storageSelect.options).forEach(option=>{option.disabled=barn&&!barnStorageKeys.includes(option.value);});storageInventory.textContent=keys.map(key=>storageLabels[key]+": "+(activeStorageChest.inventory[key]||0)+(barn?" no celeiro":warehouse?" no depósito":" no baú")+" · "+(state.inventory[key]||0)+" na mochila").join("\n")+(warehouse?"\n\nCapacidade: "+used+" / 1.500 unidades":barn?"\n\nCapacidade: "+used+" / 1.200 unidades":"");}
function openStorage(chest){activeStorageChest=chest;if(chest.isBarn&&!barnStorageKeys.includes(storageSelect.value))storageSelect.value="wheat";storagePanel.hidden=false;renderStorage();gatherPrompt.hidden=true;talkPrompt.hidden=true;storageStatus.textContent=chest.isBarn?"Celeiro da vila · trigo, sementes e alimentos · capacidade de 1.200 unidades.":chest.isWarehouse?"Depósito da vila · capacidade total de 1.500 unidades. Escolha o material e a quantidade.":"Escolha o material e a quantidade para guardar ou retirar.";}
function closeStorage(){storagePanel.hidden=true;activeStorageChest=null;Array.from(storageSelect.options).forEach(option=>option.disabled=false);}

 document.getElementById("market-close").addEventListener("click",closeMarket);marketItemSelect.addEventListener("change",renderMarket);
 document.getElementById("market-buy").addEventListener("click",()=>{const key=marketItemSelect.value,good=marketGoods[key],qty=clamp(Math.floor(Number(marketAmount.value)||1),1,99),cost=good.buy*qty;if(!state.marketStalls.length||state.coins<cost){marketStatus.textContent="Moedas insuficientes para essa compra.";return;}state.coins-=cost;state.villageStock[key]=(state.villageStock[key]||0)+qty;addMarketLog("Comprou "+qty+" "+good.label.toLowerCase()+" por "+cost+" moedas.");saveState();renderMarket();renderVillageStock();const coinsBox=document.getElementById("village-coins");if(coinsBox)coinsBox.textContent="Moedas da vila: "+state.coins;marketStatus.textContent="Compra concluída: "+qty+" "+good.label.toLowerCase()+".";});
 document.getElementById("market-sell").addEventListener("click",()=>{const key=marketItemSelect.value,good=marketGoods[key],qty=clamp(Math.floor(Number(marketAmount.value)||1),1,99),available=state.villageStock[key]||0;if(!state.marketStalls.length||available<qty){marketStatus.textContent="O estoque da vila não tem essa quantidade para vender.";return;}const earned=marketSellPrice(key)*qty;state.villageStock[key]-=qty;state.coins+=earned;addMarketLog("Vendeu "+qty+" "+good.label.toLowerCase()+" por "+earned+" moedas.");saveState();renderMarket();renderVillageStock();const coinsBox=document.getElementById("village-coins");if(coinsBox)coinsBox.textContent="Moedas da vila: "+state.coins;marketStatus.textContent="Venda concluída: +"+earned+" moedas.";});
document.getElementById("storage-close").addEventListener("click",closeStorage);
document.getElementById("storage-deposit").addEventListener("click",()=>{if(!activeStorageChest)return;const key=storageSelect.value,amount=Math.max(1,Math.floor(Number(storageAmount.value)||1)),available=state.inventory[key]||0;if(activeStorageChest.isBarn&&!barnStorageKeys.includes(key)){storageStatus.textContent="O celeiro aceita somente trigo, sementes e alimentos.";return;}if(available<1){storageStatus.textContent="Você não tem esse material na mochila.";return;}const capacity=activeStorageChest.isWarehouse?1500:activeStorageChest.isBarn?1200:Infinity,free=Math.max(0,capacity-storageUsed(activeStorageChest)),moved=Math.min(amount,available,free);if(!moved){storageStatus.textContent=activeStorageChest.isWarehouse?"O depósito está cheio. Retire materiais antes de guardar mais.":"Você não tem esse material na mochila.";return;}state.inventory[key]-=moved;activeStorageChest.inventory[key]=(activeStorageChest.inventory[key]||0)+moved;saveState();storageStatus.textContent="Guardado: "+moved+" · "+storageLabels[key]+".";renderStorage();renderCrafting();});
document.getElementById("storage-withdraw").addEventListener("click",()=>{if(!activeStorageChest)return;const key=storageSelect.value,amount=Math.max(1,Math.floor(Number(storageAmount.value)||1)),available=activeStorageChest.inventory[key]||0;if(activeStorageChest.isBarn&&!barnStorageKeys.includes(key)){storageStatus.textContent="O celeiro aceita somente trigo, sementes e alimentos.";return;}if(available<1){storageStatus.textContent="O baú não tem esse material.";return;}const moved=Math.min(amount,available);activeStorageChest.inventory[key]-=moved;state.inventory[key]=(state.inventory[key]||0)+moved;saveState();storageStatus.textContent="Retirado: "+moved+" · "+storageLabels[key]+".";renderStorage();renderCrafting();});
function nearLoom(){return placedLooms.some(b=>Math.hypot(player.x-b.position.x,player.z-b.position.z)<7);}
function nearBruna(){const npc=villagers.find(v=>v.id==="bruna");return !!npc&&Math.hypot(player.x-npc.group.position.x,player.z-npc.group.position.z)<7;}function nearTailoringShop(){return placedTailoringShops.some(b=>Math.hypot(player.x-b.position.x,player.z-b.position.z)<8);}function canUseTailor(){return tailorAtWorkshop?nearTailoringShop():nearBruna();}
const tailorRecipes={tunic:{label:"Túnica simples",cost:{fabric:2,hide:1}},trousers:{label:"Calças de tecido",cost:{fabric:1,thread:1}},cloak:{label:"Capa de lã",cost:{fabric:2,thread:2,hide:1}},vest:{label:"Colete de viajante",cost:{fabric:2,thread:1,hide:1}},dress:{label:"Vestido campestre",cost:{fabric:3,thread:2}}};
function canTailor(key){return Object.entries(tailorRecipes[key].cost).every(([k,v])=>(state.inventory[k]||0)>=v);}
function updateClothingAppearance(){const palette={natural:0x8a633e,forest:0x536b45,blue:0x496b89,wine:0x783f4b,ochre:0xb18a43};const base=state.equippedClothes.cloak?0x66516f:state.equippedClothes.dress?0x8a633e:state.equippedClothes.vest?0x76513b:state.equippedClothes.tunic?0x8a633e:0x493b30;clothingSleeveMat.color.setHex(state.clothingColor==="natural"?base:(palette[state.clothingColor]||base));}
function renderTailor(){tailorInfo.textContent="Tecidos: "+state.inventory.fabric+" · Fios: "+state.inventory.thread+" · Couro: "+state.inventory.hide+"\\nVestindo: "+Object.keys(tailorRecipes).filter(k=>state.equippedClothes[k]).map(k=>tailorRecipes[k].label).join(", ");tailorPanel.querySelectorAll("[data-tailor-action]").forEach(btn=>{const key=btn.dataset.tailorAction,owned=state.inventory[key]||0,equipped=!!state.equippedClothes[key];btn.textContent=equipped?"EM USO":owned?"VESTIR "+tailorRecipes[key].label.toUpperCase():"COSTURAR "+tailorRecipes[key].label.toUpperCase();btn.disabled=!canUseTailor()||equipped||(!owned&&!canTailor(key));});const colorSelect=document.getElementById("clothing-color");if(colorSelect)colorSelect.value=state.clothingColor||"natural";const dyeButton=document.getElementById("clothing-dye");if(dyeButton)dyeButton.disabled=!canUseTailor()||state.inventory.berries<2||!Object.values(state.equippedClothes).some(Boolean);updateClothingAppearance();}
function openTailor(){tailorAtWorkshop=false;tailorPanel.querySelector("h2").textContent="Ateliê de Bruna";tailorPanel.hidden=false;gatherPrompt.hidden=true;talkPrompt.hidden=true;renderTailor();tailorStatus.textContent="Bruna pode costurar roupas com tecidos, fios e couro. As peças são produzidas com os materiais que você trouxe.";}function openTailoringWorkshop(){tailorAtWorkshop=true;tailorPanel.querySelector("h2").textContent="Oficina de costura";tailorPanel.hidden=false;gatherPrompt.hidden=true;talkPrompt.hidden=true;renderTailor();tailorStatus.textContent="Você está trabalhando na oficina da sua vila. Produza ou vista roupas usando seus próprios materiais.";}
function closeTailor(){tailorPanel.hidden=true;tailorAtWorkshop=false;}
document.getElementById("tailor-close").addEventListener("click",closeTailor);
document.getElementById("clothing-dye").addEventListener("click",()=>{if(!canUseTailor()){tailorStatus.textContent="Aproxime-se de uma oficina de costura para tingir suas roupas.";return;}if(!Object.values(state.equippedClothes).some(Boolean)){tailorStatus.textContent="Vista uma peça antes de tingi-la.";return;}if(state.inventory.berries<2){tailorStatus.textContent="Você precisa de 2 bagas silvestres para preparar a tintura.";return;}state.inventory.berries-=2;state.clothingColor=document.getElementById("clothing-color").value;saveState();renderTailor();renderCrafting();tailorStatus.textContent="Tintura aplicada às roupas equipadas!";notify("Suas roupas ganharam uma nova cor.");});
document.getElementById("tailor-unequip").addEventListener("click",()=>{if(!canUseTailor()){tailorStatus.textContent="Aproxime-se de Bruna para trocar suas roupas.";return;}state.equippedClothes={tunic:false,trousers:false,cloak:false,vest:false,dress:false};saveState();renderTailor();tailorStatus.textContent="Você guardou as peças que estava vestindo.";});
tailorPanel.querySelectorAll("[data-tailor-action]").forEach(btn=>btn.addEventListener("click",()=>{const key=btn.dataset.tailorAction;if(!canUseTailor()){tailorStatus.textContent="Aproxime-se de Bruna para costurar ou trocar de roupa.";return;}if(state.inventory[key]>0){state.equippedClothes[key]=true;tailorStatus.textContent=tailorRecipes[key].label+" vestida.";notify(tailorRecipes[key].label+" equipada.");}else{const recipe=tailorRecipes[key];if(!canTailor(key)){tailorStatus.textContent="Materiais insuficientes. Reúna os tecidos, fios e couro indicados.";return;}for(const [material,amount] of Object.entries(recipe.cost))state.inventory[material]-=amount;state.inventory[key]++;state.equippedClothes[key]=true;tailorStatus.textContent=recipe.label+" costurada e vestida.";notify("Você costurou: "+recipe.label+".");}saveState();renderTailor();renderCrafting();}));
function renderLoom(){loomInfo.textContent="Lã: "+state.inventory.wool+" · Fios: "+state.inventory.thread+" · Tecidos: "+state.inventory.fabric;loomPanel.querySelector('[data-loom-craft="thread"]').disabled=state.inventory.wool<1;loomPanel.querySelector('[data-loom-craft="fabric"]').disabled=state.inventory.thread<3;}
function openLoom(){loomPanel.hidden=false;gatherPrompt.hidden=true;talkPrompt.hidden=true;renderLoom();loomStatus.textContent="Transforme a lã em fios e depois reúna fios suficientes para tecer um tecido.";}
function closeLoom(){loomPanel.hidden=true;}
document.getElementById("loom-close").addEventListener("click",closeLoom);
loomPanel.querySelectorAll("[data-loom-craft]").forEach(btn=>btn.addEventListener("click",()=>{if(!nearLoom()){loomStatus.textContent="Aproxime-se do tear para produzir.";return;}const key=btn.dataset.loomCraft;if(key==="thread"){if(state.inventory.wool<1){loomStatus.textContent="Você precisa de pelo menos 1 lã.";return;}state.inventory.wool--;state.inventory.thread+=2;loomStatus.textContent="Fiação concluída: +2 fios.";notify("A lã foi transformada em 2 fios.");}else{if(state.inventory.thread<3){loomStatus.textContent="Reúna 3 fios para tecer 1 tecido.";return;}state.inventory.thread-=3;state.inventory.fabric++;loomStatus.textContent="Tecelagem concluída: +1 tecido.";notify("Um tecido foi produzido.");}saveState();renderLoom();renderCrafting();}));
function nearCarpentry(){return placedCarpentryShops.some(b=>Math.hypot(player.x-b.position.x,player.z-b.position.z)<8);}
const carpentryRecipes={planks:{label:"Tábuas de madeira",cost:3,gain:2},beams:{label:"Vigas de madeira",cost:4,gain:1}};
function canCraftCarpentry(key){return nearCarpentry()&&state.inventory.wood>=carpentryRecipes[key].cost;}
function renderCarpentry(){carpentryInventory.textContent="Madeira bruta: "+state.inventory.wood+" · Tábuas: "+state.inventory.planks+" · Vigas: "+state.inventory.beams;carpentryPanel.querySelectorAll("[data-carpentry-craft]").forEach(btn=>btn.disabled=!canCraftCarpentry(btn.dataset.carpentryCraft));}
function openCarpentry(){carpentryPanel.hidden=false;renderCarpentry();gatherPrompt.hidden=true;talkPrompt.hidden=true;}
function closeCarpentry(){carpentryPanel.hidden=true;}
document.getElementById("carpentry-close").addEventListener("click",closeCarpentry);
carpentryPanel.querySelectorAll("[data-carpentry-craft]").forEach(btn=>btn.addEventListener("click",()=>{const key=btn.dataset.carpentryCraft,r=carpentryRecipes[key];if(!canCraftCarpentry(key)){carpentryStatus.textContent="Aproxime-se da oficina e reúna madeira suficiente.";return;}state.inventory.wood-=r.cost;state.inventory[key]+=r.gain;saveState();carpentryStatus.textContent=r.label+" produzidas: +"+r.gain+". Materiais atualizados.";notify(r.label+" produzidas.");renderCarpentry();}));
function renderCrafting(){const shelterButton=craftPanel.querySelector("[data-build-shelter]");if(shelterButton)shelterButton.disabled=!canBuildShelter();const houseButton=craftPanel.querySelector("[data-build-house]");if(houseButton)houseButton.disabled=!canBuildVillageHouse();const workbenchButton=craftPanel.querySelector("[data-build-workbench]");if(workbenchButton)workbenchButton.disabled=!canBuildWorkbench();const carpentryButton=craftPanel.querySelector("[data-build-carpentry]");if(carpentryButton)carpentryButton.disabled=!canBuildCarpentry();const chestBuildButton=craftPanel.querySelector("[data-build-chest]");if(chestBuildButton)chestBuildButton.disabled=!canBuildChest();const warehouseBuildButton=craftPanel.querySelector("[data-build-warehouse]");if(warehouseBuildButton)warehouseBuildButton.disabled=!canBuildWarehouse();const barnBuildButton=craftPanel.querySelector("[data-build-barn]");if(barnBuildButton)barnBuildButton.disabled=!canBuildBarn();const bakeryBuildButton=craftPanel.querySelector("[data-build-bakery]");if(bakeryBuildButton)bakeryBuildButton.disabled=!canBuildBakery();const chickenCoopButton=craftPanel.querySelector("[data-build-chicken-coop]");if(chickenCoopButton)chickenCoopButton.disabled=!canBuildChickenCoop();const sheepPenButton=craftPanel.querySelector("[data-build-sheep-pen]");if(sheepPenButton)sheepPenButton.disabled=false;const loomButton=craftPanel.querySelector("[data-build-loom]");if(loomButton)loomButton.disabled=!canBuildLoom();const tailoringButton=craftPanel.querySelector("[data-build-tailoring]");if(tailoringButton)tailoringButton.disabled=!canBuildTailoring();const marketButton=craftPanel.querySelector("[data-build-market]");if(marketButton)marketButton.disabled=!canBuildMarket();const fieldButton=craftPanel.querySelector("[data-build-field]");if(fieldButton)fieldButton.disabled=!state.tools.hoe;inventoryText.textContent="Bagas: "+state.inventory.berries+"   Galhos: "+state.inventory.branches+"   Pedras: "+state.inventory.stones+"   Fibras: "+state.inventory.fiber+"   Madeira: "+state.inventory.wood+"   Carne: "+state.inventory.meat+"   Couro: "+state.inventory.hide+"   Sementes: "+state.inventory.wheatSeeds+"   Trigo: "+state.inventory.wheat+"   Ovos: "+state.inventory.eggs+"   Lã: "+state.inventory.wool+"   Fios: "+state.inventory.thread+"   Tecidos: "+state.inventory.fabric+"   Túnicas: "+state.inventory.tunic+"   Calças: "+state.inventory.trousers+"   Capas: "+state.inventory.cloak+"\\nEnxada: "+(state.tools.hoe?"fabricada":"não fabricada")+"   Lança: "+(state.tools.spear?"fabricada":"não fabricada")+"   Machado: "+(state.tools.axeAdvanced?"reforçado":state.tools.axe?"rudimentar":"não fabricado")+"   Picareta: "+(state.tools.pickaxeAdvanced?"reforçada":state.tools.pickaxe?"rudimentar":"não fabricada")+"\\nTochas: "+state.items.torches+"   Fogueiras: "+state.items.campfires;craftPanel.querySelectorAll("[data-craft]").forEach(btn=>{const key=btn.dataset.craft;btn.disabled=!canCraft(key);});campfirePlace.hidden=state.items.campfires<1;const eatBerries=document.getElementById("eat-berries");if(eatBerries)eatBerries.disabled=state.inventory.berries<1||state.hunger>=100;const hungerCraft=document.getElementById("hunger-craft-status");if(hungerCraft)hungerCraft.textContent="Fome: "+Math.round(state.hunger)+"% · Bagas: "+state.inventory.berries+" · Refeições: "+state.inventory.meals;}
function openCrafting(){craftVisible=true;craftPanel.hidden=false;gatherPrompt.hidden=true;renderCrafting();}
function closeCrafting(){craftVisible=false;craftPanel.hidden=true;}
const benchPanel=document.getElementById("bench-panel"),benchInventory=document.getElementById("bench-inventory"),benchStatus=document.getElementById("bench-status");
function renderBench(){benchInventory.textContent="Madeira: "+state.inventory.wood+" · Pedras: "+state.inventory.stones+" · Galhos: "+state.inventory.branches+" · Fibras: "+state.inventory.fiber+"\\nMachado: "+(state.tools.axeAdvanced?"reforçado":state.tools.axe?"rudimentar":"não fabricado")+" · Picareta: "+(state.tools.pickaxeAdvanced?"reforçada":state.tools.pickaxe?"rudimentar":"não fabricada");benchPanel.querySelectorAll("[data-bench-craft]").forEach(btn=>{btn.disabled=!canCraftAdvanced(btn.dataset.benchCraft);});}
