document.getElementById("bench-close").addEventListener("click",closeBench);
benchPanel.querySelectorAll("[data-bench-craft]").forEach(btn=>btn.addEventListener("click",()=>{const key=btn.dataset.benchCraft,r=advancedRecipes[key];if(!canCraftAdvanced(key)){benchStatus.textContent="Você precisa estar perto da bancada, ter a ferramenta rudimentar e reunir todos os materiais.";return;}for(const [k,v] of Object.entries(r.cost))state.inventory[k]-=v;state.tools[key+"Advanced"]=true;saveState();benchStatus.textContent=r.label+" fabricado com sucesso.";notify("Você fabricou: "+r.label+".");renderBench();}));
craftOpen.addEventListener("click",openCrafting);craftClose.addEventListener("click",closeCrafting);
document.getElementById("eat-berries").addEventListener("click",()=>{if(state.inventory.berries<1){craftStatus.textContent="Você precisa coletar bagas silvestres primeiro.";return;}if(state.hunger>=100){craftStatus.textContent="Você não está com fome agora.";return;}state.inventory.berries--;state.hunger=Math.min(100,state.hunger+25);saveState();craftStatus.textContent="Você comeu bagas silvestres. A fome foi reduzida.";notify("Você se alimentou: +25 de saciedade.");updateClock(0);renderCrafting();});
craftPanel.querySelectorAll("[data-craft]").forEach(btn=>btn.addEventListener("click",()=>{const key=btn.dataset.craft,r=recipes[key];if(!canCraft(key)){craftStatus.textContent="Ainda faltam materiais para esta receita.";return;}for(const [k,v] of Object.entries(r.cost))state.inventory[k]-=v;if(key==="axe")state.tools.axe=true;else if(key==="pickaxe")state.tools.pickaxe=true;else if(key==="spear")state.tools.spear=true;else if(key==="hoe")state.tools.hoe=true;else if(key==="torch")state.items.torches++;else state.items.campfires++;saveState();craftStatus.textContent=r.label+" fabricado com sucesso.";notify(r.label+" fabricado.");renderCrafting();}));

campfirePlace.addEventListener("click",()=>startPlacement("campfire"));const shelterBuildButton=craftPanel.querySelector("[data-build-shelter]");shelterBuildButton?.addEventListener("click",()=>startPlacement("shelter"));const houseBuildButton=craftPanel.querySelector("[data-build-house]");houseBuildButton?.addEventListener("click",()=>startPlacement("house"));const workbenchBuildButton=craftPanel.querySelector("[data-build-workbench]");workbenchBuildButton?.addEventListener("click",()=>startPlacement("workbench"));const carpentryBuildButton=craftPanel.querySelector("[data-build-carpentry]");carpentryBuildButton?.addEventListener("click",()=>startPlacement("carpentry"));const chestBuildButton=craftPanel.querySelector("[data-build-chest]");chestBuildButton?.addEventListener("click",()=>startPlacement("chest"));const warehouseBuildButton=craftPanel.querySelector("[data-build-warehouse]");warehouseBuildButton?.addEventListener("click",()=>startPlacement("warehouse"));const barnBuildButton=craftPanel.querySelector("[data-build-barn]");barnBuildButton?.addEventListener("click",()=>startPlacement("barn"));const millBuildButton=craftPanel.querySelector("[data-build-mill]");millBuildButton?.addEventListener("click",()=>startPlacement("mill"));const bakeryBuildButton=craftPanel.querySelector("[data-build-bakery]");bakeryBuildButton?.addEventListener("click",()=>startPlacement("bakery"));const tavernBuildButton=craftPanel.querySelector("[data-build-tavern]");tavernBuildButton?.addEventListener("click",()=>startPlacement("tavern"));const marketBuildButton=craftPanel.querySelector("[data-build-market]");marketBuildButton?.addEventListener("click",()=>startPlacement("market"));craftPanel.querySelectorAll("[data-build-decoration]").forEach(button=>button.addEventListener("click",()=>startPlacement(button.dataset.buildDecoration)));craftPanel.querySelectorAll("[data-build-defense]").forEach(button=>button.addEventListener("click",()=>startPlacement(button.dataset.buildDefense)));const fieldBuildButton=craftPanel.querySelector("[data-build-field]");fieldBuildButton?.addEventListener("click",()=>startPlacement("field"));const chickenCoopBuildButton=craftPanel.querySelector("[data-build-chicken-coop]");chickenCoopBuildButton?.addEventListener("click",()=>startPlacement("chickenCoop"));const sheepPenBuildButton=craftPanel.querySelector("[data-build-sheep-pen]");sheepPenBuildButton?.addEventListener("click",()=>startPlacement("sheepPen"));const loomBuildButton=craftPanel.querySelector("[data-build-loom]");loomBuildButton?.addEventListener("click",()=>startPlacement("loom"));const tailoringBuildButton=craftPanel.querySelector("[data-build-tailoring]");tailoringBuildButton?.addEventListener("click",()=>startPlacement("tailoring"));placementConfirm.addEventListener("click",confirmPlacement);placementCancel.addEventListener("click",cancelPlacement);
document.getElementById("placement-rotate-left").addEventListener("click",()=>rotateShelter(-Math.PI/4));document.getElementById("placement-rotate-right").addEventListener("click",()=>rotateShelter(Math.PI/4));
function rotateShelter(delta){if(!placementMode||!(selectedPlacementKind==="shelter"||selectedPlacementKind==="house"||selectedPlacementKind==="workbench"||selectedPlacementKind==="carpentry"||selectedPlacementKind==="chest"||selectedPlacementKind==="warehouse"||selectedPlacementKind==="barn"||selectedPlacementKind==="mill"||selectedPlacementKind==="bakery"||selectedPlacementKind==="tavern"||selectedPlacementKind==="field"||selectedPlacementKind==="chickenCoop"||selectedPlacementKind==="sheepPen"||selectedPlacementKind==="loom"||selectedPlacementKind==="tailoring"||selectedPlacementKind==="palisade"||selectedPlacementKind==="gate"||selectedPlacementKind==="watchtower")||!activeShelterPreview)return;placementRotation=(placementRotation+delta+Math.PI*2)%(Math.PI*2);activeShelterPreview.rotation.y=placementRotation;}
function performGather(target){if(!target)return;if(target.kind==="prisonerRelease"){if(!state.infiltration.cellFound||state.prisonerRescue.released||outpostAlert){notify("Espere os guardas se afastarem para libertar os prisioneiros.");return;}state.prisonerRescue.released=true;rescuedPrisoners.forEach(p=>p.group.visible=true);saveState();notify("As celas foram abertas! Três sobreviventes estão com você. Fuja do posto e leve todos até Alina.");objective.querySelector("strong").textContent="Conduza os sobreviventes até Alina";objective.querySelector("p").textContent="Os três prisioneiros estão seguindo você. Evite os guardas e retorne à Vila Vizinha.";renderQuestJournal();currentGatherable=null;gatherPrompt.hidden=true;return;}if(target.kind==="prisonerCell"){if(!state.rescuePlan.ready||outpostAlert){notify("Aguarde uma oportunidade segura para observar as celas.");return;}state.infiltration.cellFound=true;saveState();cellMarker.visible=false;notify("Você encontrou as celas! Há prisioneiros vivos no interior do posto. Saia sem alertar os guardas.");objective.querySelector("strong").textContent="Localize uma saída segura";objective.querySelector("p").textContent="Você confirmou que há prisioneiros vivos nas celas. A missão de resgate será a próxima etapa.";renderQuestJournal();currentGatherable=null;gatherPrompt.hidden=true;return;}if(target.kind==="rescuePrepClue"){const clue=target.clue;if(!state.rescuePrep.clues.includes(clue.id)){state.rescuePrep.clues.push(clue.id);const marker=rescuePrepMarkers.find(item=>item.id===clue.id);if(marker)marker.group.visible=false;saveState();const count=state.rescuePrep.clues.length;notify(clue.message+" ("+count+"/4 descobertas)");objective.querySelector("strong").textContent=count>=4?"Volte a falar com Alina":"Investigue o Posto da Garganta";objective.querySelector("p").textContent=count>=4?"Você reuniu as quatro informações. Retorne à Vila Vizinha e converse com Alina.":"Descobertas: "+count+"/4. Continue investigando o posto.";renderQuestJournal();}currentGatherable=null;gatherPrompt.hidden=true;return;}if(target.kind==="prisonerClue"){const clue=target.clue;if(!state.prisonerQuest.clues.includes(clue.id)){state.prisonerQuest.clues.push(clue.id);const marker=prisonerMarkers.find(item=>item.id===clue.id);if(marker)marker.group.visible=false;saveState();const count=state.prisonerQuest.clues.length;notify(clue.message+" ("+count+"/3 rastros)");objective.querySelector("strong").textContent=count>=3?"Volte a falar com Alina":"Siga os rastros da caravana";objective.querySelector("p").textContent=count>=3?"Você encontrou as três pistas. Retorne à Vila Vizinha e converse com Alina.":"Rastros encontrados: "+count+"/3. Continue seguindo para o leste.";renderQuestJournal();}currentGatherable=null;gatherPrompt.hidden=true;return;}if(target.kind==="questClue"){const clue=target.clue;if(!state.mainQuest.clues.includes(clue.id)){state.mainQuest.clues.push(clue.id);const marker=questMarkers.find(item=>item.id===clue.id);if(marker)marker.group.visible=false;saveState();const count=state.mainQuest.clues.length;notify(clue.message+" ("+count+"/3 pistas)");objective.querySelector("strong").textContent=count>=3?"Volte à Vila Vizinha e fale com Alina":"Investigue os rastros dos bárbaros";objective.querySelector("p").textContent=count>=3?"Você reuniu as três pistas. Encontre Alina na Vila Vizinha.":"Pistas encontradas: "+count+"/3. Continue explorando o vale.";renderQuestJournal();}currentGatherable=null;gatherPrompt.hidden=true;return;}if(target.kind==="chickenCoop"){openChickenCoop(target.index);return;}if(target.kind==="sheepPen"){openSheepPen(target.index);return;}if(target.kind==="field"){const entry=target.field;if(entry.data.plantedDay===null||entry.data.plantedDay===undefined){if(!state.tools.hoe){notify("Fabrique uma enxada para trabalhar a terra.");return;}if(state.inventory.wheatSeeds<1){notify("Você precisa encontrar sementes silvestres antes de plantar.");return;}state.inventory.wheatSeeds--;entry.data.plantedDay=state.day;entry.stage=-1;refreshFieldVisual(entry);saveState();notify("Trigo plantado. A colheita ficará pronta em 3 dias.");}else if(state.day-entry.data.plantedDay>=2){state.inventory.wheat+=5;state.inventory.wheatSeeds++;entry.data.plantedDay=null;entry.stage=-1;refreshFieldVisual(entry);saveState();notify("Colheita realizada: +5 trigo e +1 semente.");}else{const remaining=3-(state.day-entry.data.plantedDay);notify("O trigo ainda está crescendo. Faltam "+remaining+" dia(s) para a colheita.");}renderCrafting();return;}if(target.kind==="animal"){if(!state.tools.spear){notify("Você precisa fabricar uma lança rudimentar para caçar.");return;}const animal=target.animal;state.huntedAnimals=state.huntedAnimals.filter(v=>v.id!==animal.id);state.huntedAnimals.push({id:animal.id,day:state.day});animal.group.visible=false;animal.alive=false;state.inventory.meat+=2;state.inventory.hide+=1;notify("Caça realizada: +2 carnes e +1 couro.");saveState();renderCrafting();currentGatherable=null;gatherPrompt.hidden=true;return;}if(target.kind==="tree"){const index=target.index;setTreeVisible(index,false);state.felledTrees.push({index,day:state.day});const woodGain=state.tools.axeAdvanced?4:2,branchGain=state.tools.axeAdvanced?3:2;state.inventory.wood+=woodGain;state.inventory.branches+=branchGain;notify("Árvore cortada: +"+woodGain+" madeiras e +"+branchGain+" galhos.");}else{const node=target.node;if(node.type==="ore"&&!state.tools.pickaxe){notify("Você precisa de uma picareta para extrair este veio de pedra.");return;}if(node.type==="branch")state.inventory.branches+=node.amount;else if(node.type==="stone")state.inventory.stones+=node.amount;else if(node.type==="fiber")state.inventory.fiber+=node.amount;else if(node.type==="berry")state.inventory.berries+=node.amount;else if(node.type==="seed")state.inventory.wheatSeeds+=node.amount;else state.inventory.stones+=node.amount*(node.type==="ore"&&state.tools.pickaxeAdvanced?2:1);state.harvestedNodes[node.id]=state.day;node.group.visible=false;notify(node.type==="berry"?"Bagas silvestres coletadas: +"+node.amount+".":node.type==="seed"?"Sementes de trigo silvestre coletadas: +"+node.amount+".":node.type==="ore"?"Minério extraído: +"+node.amount+" pedras.":"Recursos coletados.");}saveState();renderCrafting();currentGatherable=null;gatherPrompt.hidden=true;}
gatherButton.addEventListener("click",()=>{if(currentGatherable?.kind==="storage"){openStorage(currentGatherable.chest);return;}performGather(currentGatherable);});
 let pendingPlot=null;
 function validPlot(x,z){if(Math.abs(x)>82||Math.abs(z)>82)return"Escolha uma área mais distante dos limites do vale.";if(riverDistance(x,z)<17)return"Esse terreno fica muito perto do rio. Procure uma área mais segura.";if(Math.hypot(x-48,z+82)<28)return"Escolha um terreno afastado da Vila Vizinha.";const base=groundHeight(x,z);for(const [dx,dz] of [[-10,0],[10,0],[0,-10],[0,10],[-7,-7],[7,-7],[-7,7],[7,7]])if(Math.abs(groundHeight(x+dx,z+dz)-base)>1.65)return"Esse terreno é muito inclinado. Procure uma área mais plana.";return"";}
